	public bool CheckErrorMessageTrade() {
		SetTradeErrorMesage();
		if (PlayerWork.unionSaveData.penartyCounter > 0)
		{
			unionMsgSystemWindow.OpenMsgWindow(0, UnionTextData.SpeakerID.SYSTEM);
			Sequencer.update -= PenaltyErrorMsgUpdate;
			Sequencer.update += PenaltyErrorMsgUpdate;
			return true;
		}

		int pokeCount = 0;
		PokeParty party = PlayerWork.playerParty;
		uint memberCount = party.GetMemberCount();
		for (uint i = 0; i < memberCount; i++)
		{
			if (!party.GetMemberPointer(i).IsEgg(EggCheckType.BOTH_EGG))
				pokeCount++;
		}

		PokemonParam pokemonParam = new PokemonParam();
		int trayMax = Dpr.Box.BoxWork.GetTrayMax();
		for (int tray = 0; tray < trayMax; tray++)
		{
			for (int pos = 0; pos < 30; pos++)
			{
				Dpr.Box.BoxPokemonWork.GetPokemon(pokemonParam, tray, pos);
				if (!pokemonParam.IsNull() && !pokemonParam.IsEgg(EggCheckType.BOTH_EGG))
					pokeCount++;
			}
		}

		if (pokeCount < TRADE_OK_MEMBER_POKE_COUNT)
		{
			unionMsgSystemWindow.OpenMsgWindow(1, UnionTextData.SpeakerID.SYSTEM);
			unionMsgSystemWindow.GetNowMessage().inputCloseEnabled = true;
			unionMsgSystemWindow.GetNowMessage().onFinishedCloseWindow = PlayerInputEnabled;
		}
		return pokeCount < TRADE_OK_MEMBER_POKE_COUNT;
	}
	public bool CheckBallDeco() {
		SetSystemMessageBallDeco();
		if (FlagWork.GetWork(Dpr.EvScript.EvWork.WORK_INDEX.WK_SCENE_C01) == 4)
		{
			Dpr.BallDeco.CapsuleData[] capsuleDatas = Dpr.BallDeco.BallDecoWork.m_ballDecoData.CapsuleDatas;
			if (capsuleDatas.Length > 0)
			{
				int sealCapsuleCount = 0;
				for (int i = 0; i < capsuleDatas.Length; i++)
				{
					if (capsuleDatas[i].AffixSealCount != 0)
						sealCapsuleCount++;
				}

				if (sealCapsuleCount > 0)
				{
					if (sealCapsuleCount < Dpr.BallDeco.BallDecoWork.GetCapsuleCount())
						return true;

					OpenSystemMsgWindow(1, UnionTextData.SpeakerID.SYSTEM);
				}
				else
				{
					OpenSystemMsgWindow(2, UnionTextData.SpeakerID.SYSTEM);
				}
			}
			else
			{
				OpenSystemMsgWindow(2, UnionTextData.SpeakerID.SYSTEM);
			}
		}
		else
		{
			OpenSystemMsgWindow(0, UnionTextData.SpeakerID.SYSTEM);
		}

		unionMsgSystemWindow.GetNowMessage().inputCloseEnabled = true;
		unionMsgSystemWindow.GetNowMessage().onFinishedCloseWindow = PlayerInputEnabled;
		return false;
	}
